<script lang="ts">
	import {
		PROJECT_CEILING_SENTENCE,
		UPLOAD_CEILING_LIST,
		formatCap,
		uploadFailureMessage,
		uploadTooLargeMessage
	} from '$lib/upload-limits';
	import { notebookPhotoRefusal } from '$lib/notebook/photo-prepare';

	/**
	 * ONE MEGABYTE OVER, WHATEVER THE CEILING IS. Every refusal below is
	 * generated by asking the real function about a file a megabyte past the
	 * real limit, so nothing on this page is a string somebody typed. A row
	 * whose ceiling is not ours gets a plausible oversize file instead (30 MB),
	 * because there is no limit to be a megabyte past.
	 */
	const overBy = (max: number | null) => (max == null ? 30 * 1024 * 1024 : max + 1024 * 1024);

	const rows = UPLOAD_CEILING_LIST.map((c) => ({
		ceiling: c,
		size: overBy(c.maxBytes),
		cap: c.maxBytes == null ? 'not set here' : formatCap(c.maxBytes),
		refusal: uploadTooLargeMessage(c.id, overBy(c.maxBytes))
	}));

	/**
	 * THE FOUR OTHER WAYS AN UPLOAD FAILS, on one path, so the discrimination
	 * is readable rather than asserted. The one that matters is the third: a
	 * file well under the ceiling, refused for a reason that has nothing to do
	 * with size, must not be told about size.
	 */
	const others: { key: string; about: string; message: string }[] = [
		{
			key: 'too-large-project',
			about: 'Storage refused it for size, on a path whose ceiling is not set here',
			message: uploadFailureMessage({
				id: 'foundry-bundle',
				status: 413,
				detail: 'The object exceeded the maximum allowed size',
				sizeBytes: 30 * 1024 * 1024
			})
		},
		{
			key: 'denied',
			about: 'A 40 MB file into a 200 MB bucket, refused by row-level security',
			message: uploadFailureMessage({
				id: 'classroom-submission',
				status: 403,
				detail: 'new row violates row-level security policy',
				sizeBytes: 40 * 1024 * 1024
			})
		},
		{
			key: 'network',
			about: 'The connection dropped part way through',
			message: uploadFailureMessage({ id: 'maps-photo', status: 0, detail: 'Failed to fetch' })
		},
		{
			key: 'silent',
			about: 'The server answered a status and said nothing at all',
			message: uploadFailureMessage({ id: 'avatar', status: 500, detail: '' })
		},
		{
			key: 'unanticipated',
			about: 'Something nobody wrote a branch for, kept in its own words',
			message: uploadFailureMessage({
				id: 'maps-photo',
				status: 500,
				detail: 'Internal error while writing object'
			})
		}
	];

	/** The notebook gate, both directions, since it is the one this bundle wired. */
	const notebook = [
		{ key: 'empty', label: '0 bytes', message: notebookPhotoRefusal({ size: 0 }) },
		{ key: 'under', label: '3 MB', message: notebookPhotoRefusal({ size: 3 * 1024 * 1024 }) },
		{ key: 'over', label: '9 MB', message: notebookPhotoRefusal({ size: 9 * 1024 * 1024 }) }
	];
</script>

<svelte:head><title>Upload ceilings</title></svelte:head>

<main class="harness" data-testid="upload-limits-root">
	<h1>Upload ceilings</h1>
	<p class="lede">
		Every upload ceiling in the portal, and the sentence each one produces. Nothing here is
		typed: each refusal is the real function asked about a real size.
	</p>

	<h2>Every ceiling, and what it says</h2>
	<ul class="rows" data-testid="upload-limits-table">
		{#each rows as row (row.ceiling.id)}
			<li data-testid="upload-limits-row" data-path={row.ceiling.id}>
				<p class="case">
					<span
						class="tag"
						data-tag={row.ceiling.maxBytes == null ? 'unstated' : 'stated'}
						data-testid="upload-limits-tag">{row.ceiling.maxBytes == null ? 'not ours' : 'stated'}</span
					>
					{row.ceiling.id}
				</p>
				<p class="outcome"><strong>{row.cap}</strong> for {row.ceiling.label}</p>
				<p class="outcome dim">
					{row.ceiling.bucket ?? 'no bucket: the bytes go to one of our own routes'}
					&middot; {row.ceiling.guards.join(', ')}
				</p>
				<p class="refusal" data-testid="upload-limits-refusal">{row.refusal}</p>
				<p class="stated">{row.ceiling.statedBy}</p>
			</li>
		{/each}
	</ul>

	<h2>The ceiling nobody here can read</h2>
	<p class="note" data-testid="upload-limits-project-note">{PROJECT_CEILING_SENTENCE}</p>

	<h2>Failing for a reason that is not size</h2>
	<ul class="rows" data-testid="upload-limits-others">
		{#each others as row (row.key)}
			<li data-testid="upload-limits-other" data-case={row.key}>
				<p class="case">{row.about}</p>
				<p class="refusal" data-testid="upload-limits-other-message">{row.message}</p>
			</li>
		{/each}
	</ul>

	<h2>The notebook photo gate</h2>
	<ul class="rows" data-testid="upload-limits-notebook">
		{#each notebook as row (row.key)}
			<li data-case={row.key}>
				<p class="case">{row.label}</p>
				<p class="refusal">{row.message ?? 'accepted, nothing to say'}</p>
			</li>
		{/each}
	</ul>
</main>

