	}
	.rows {
		list-style: none;
		margin: 0.8rem 0 0;
		padding: 0;
		display: grid;
		gap: 0.7rem;
	}
	.rows li {
		border: 1px solid var(--boundary);
		border-radius: var(--radius-2, 4px);
		padding: 0.7rem 0.8rem;
		/* min-width: 0 so a long sentence cannot push the page wider than the
		   viewport at 375px -- a grid child's automatic minimum is its
		   min-content, and `overflow: hidden` does not reduce that. */
		min-width: 0;
	}
	.rows p {
		margin: 0 0 0.3rem;
		min-width: 0;
		overflow-wrap: anywhere;
	}
	.case {
		font-family: var(--font-mono);
		font-size: 0.82rem;
		color: var(--text-1);
	}
	.outcome {
		color: var(--text-1);
		font-size: 0.9rem;
	}
	.dim {
		color: var(--text-2);
		font-size: 0.82rem;
	}
	.refusal {
		color: var(--text-1);
		font-size: 0.9rem;
